15	/**
16	 * Base structural evaluator.
17	 */
18	abstract class StructuralEvaluator extends Evaluator {
19	    final Evaluator evaluator;
20	    boolean wantsNodes; // if the evaluator requested nodes, not just elements
21	
22	    public StructuralEvaluator(Evaluator evaluator) {
23	        this.evaluator = evaluator;
24	        wantsNodes = evaluator.wantsNodes();
25	    }
26	
27	    @Override
28	    boolean wantsNodes() {
29	        return wantsNodes;
30	    }
31	
32	    // Memoize inner matches, to save repeated re-evaluations of parent, sibling etc.
33	    // root + element: Boolean matches. ThreadLocal in case the Evaluator is compiled then reused across multi threads
34	    final ThreadLocal<Map<Node, Map<Node, Boolean>>> threadMemo = ThreadLocal.withInitial(WeakHashMap::new);
35	
36	    boolean memoMatches(final Element root, final Node node) {
37	        Map<Node, Map<Node, Boolean>> rootMemo = threadMemo.get();
38	        Map<Node, Boolean> memo = rootMemo.computeIfAbsent(root, r -> new WeakHashMap<>());
39	        return memo.computeIfAbsent(node, test -> evaluator.matches(root, test));
40	    }
41	
42	    @Override protected void reset() {
43	        threadMemo.remove();
44	        evaluator.reset();
45	        super.reset();
46	    }
47	
48	    @Override
49	    public boolean matches(Element root, Element element) {
50	        return evaluateMatch(root, element);
51	    }
52	
53	    @Override
54	    boolean matches(Element root, LeafNode leafNode) {
55	        return evaluateMatch(root, leafNode);
56	    }
57	
58	    abstract boolean evaluateMatch(Element root, Node node);
59	
60	    static class Root extends Evaluator {
61	        @Override
62	        public boolean matches(Element root, Element element) {
63	            return root == element;
64	        }
65	
66	        @Override protected int cost() {
67	            return 1;
68	        }
69	
70	        @Override public String toString() {
71	            return ">";
72	        }
73	    }
74	
75	    static class Has extends StructuralEvaluator {
76	        static final SoftPool<NodeIterator<Node>> NodeIterPool =
77	            new SoftPool<>(() -> new NodeIterator<>(new TextNode(""), Node.class));
78	        // the element here is just a placeholder so this can be final - gets set in restart()
79	
80	        private final boolean checkSiblings; // evaluating against siblings (or children)
81	
82	        public Has(Evaluator evaluator) {
83	            super(evaluator);
84	            checkSiblings = evalWantsSiblings(evaluator);
85	        }
86	
87	        @Override public boolean matches(Element root, Element element) {
88	            if (checkSiblings) { // evaluating against siblings
89	                for (Element sib = element.firstElementSibling(); sib != null; sib = sib.nextElementSibling()) {
90	                    if (sib != element && evaluator.matches(element, sib)) { // don't match against self
91	                        return true;
92	                    }
93	                }
94	            }
95	            // otherwise we only want to match children (or below), and not the input element. And we want to minimize GCs so reusing the Iterator obj
96	            NodeIterator<Node> it = NodeIterPool.borrow();
97	            it.restart(element);
98	            try {
99	                while (it.hasNext()) {
100	                    Node node = it.next();
101	                    if (node == element) continue; // don't match self, only descendants
102	                    if (evaluator.matches(element, node)) {
103	                        return true;
104	                    }
105	                }
106	            } finally {
107	                NodeIterPool.release(it);
108	            }
109	            return false;
110	        }
111	
112	        @Override
113	        boolean evaluateMatch(Element root, Node node) {
114	            return false; // unused; :has(::comment)) goes via implicit root combinator
115	        }
116	
117	        /* Test if the :has sub-clause wants sibling elements (vs nested elements) - will be a Combining eval */
118	        private static boolean evalWantsSiblings(Evaluator eval) {
119	            if (eval instanceof CombiningEvaluator) {
120	                CombiningEvaluator ce = (CombiningEvaluator) eval;
121	                for (Evaluator innerEval : ce.evaluators) {
122	                    if (innerEval instanceof PreviousSibling || innerEval instanceof ImmediatePreviousSibling)
123	                        return true;
124	                }
125	            }
126	            return false;
127	        }
128	
129	        @Override protected int cost() {
130	            return 10 * evaluator.cost();
131	        }
132	
133	        @Override
134	        public String toString() {
135	            return String.format(":has(%s)", evaluator);
136	        }
137	    }
138	
139	    /** Implements the :is(sub-query) pseudo-selector */
140	    static class Is extends StructuralEvaluator {
141	        public Is(Evaluator evaluator) {
142	            super(evaluator);
143	        }
144	
145	        @Override
146	        boolean evaluateMatch(Element root, Node node) {
147	            return evaluator.matches(root, node);
148	        }
149	
150	        @Override protected int cost() {
151	            return 2 + evaluator.cost();
152	        }
153	
154	        @Override
155	        public String toString() {
156	            return String.format(":is(%s)", evaluator);
157	        }
158	    }
159	
160	    static class Not extends StructuralEvaluator {
161	        public Not(Evaluator evaluator) {
162	            super(evaluator);
163	        }
164	
165	        @Override
166	        boolean evaluateMatch(Element root, Node node) {
167	            return !memoMatches(root, node);
168	        }
169	
170	        @Override protected int cost() {
171	            return 2 + evaluator.cost();
172	        }
173	
174	        @Override
175	        public String toString() {
176	            return String.format(":not(%s)", evaluator);
177	        }
178	    }
179	
180	    /**
181	     Any Ancestor (i.e., ascending parent chain.).
182	     */
183	    static class Ancestor extends StructuralEvaluator {
184	        public Ancestor(Evaluator evaluator) {
185	            super(evaluator);
186	        }
187	
188	        @Override
189	        boolean evaluateMatch(Element root, Node node) {
190	            if (root == node)
191	                return false;
192	
193	            for (Node parent = node.parent(); parent != null; parent = parent.parent()) {
194	                if (memoMatches(root, parent))
195	                    return true;
196	                if (parent == root)
197	                    break;
198	            }
199	            return false;
200	        }
201	
202	        @Override
203	        protected int cost() {
204	            return 8 * evaluator.cost(); // probably lower than has(), but still significant, depending on doc and el depth.
205	        }
206	
207	        @Override
208	        public String toString() {
209	            return String.format("%s ", evaluator);
210	        }
211	    }
212	
213	    /**
214	     Holds a list of evaluators for one > two > three immediate parent matches, and the final direct evaluator under
215	     test. To match, these are effectively ANDed together, starting from the last, matching up to the first.
216	     */
217	    static class ImmediateParentRun extends StructuralEvaluator {
218	        final ArrayList<Evaluator> evaluators = new ArrayList<>();
219	        int cost = 2;
220	
221	        public ImmediateParentRun(Evaluator evaluator) {
222	            super(evaluator);
223	            evaluators.add(evaluator);
224	            cost += evaluator.cost();
225	        }
226	
227	        void add(Evaluator evaluator) {
228	            evaluators.add(evaluator);
229	            cost += evaluator.cost();
230	            wantsNodes |= evaluator.wantsNodes();
231	        }
232	
233	        @Override boolean evaluateMatch(Element root, Node node) {
234	            if (node == root)
235	                return false; // cannot match as the second eval (first parent test) would be above the root
236	
237	            for (int i = evaluators.size() -1; i >= 0; --i) {
238	                if (node == null)
239	                    return false;
240	                Evaluator eval = evaluators.get(i);
241	                if (!eval.matches(root, node))
242	                    return false;
243	                node = node.parent();
244	            }
245	            return true;
246	        }
247	
248	        @Override protected int cost() {
249	            return cost;
250	        }
251	
252	        @Override
253	        protected void reset() {
254	            for (Evaluator evaluator : evaluators) {
255	                evaluator.reset();
256	            }
257	            super.reset();
258	        }
259	
260	        @Override
261	        public String toString() {
262	            return StringUtil.join(evaluators, " > ");
263	        }
264	    }
265	
266	    static class PreviousSibling extends StructuralEvaluator {
267	        public PreviousSibling(Evaluator evaluator) {
268	            super(evaluator);
269	        }
270	
271	        // matches any previous sibling, so can be same in Element only or wantsNodes context
272	        @Override boolean evaluateMatch(Element root, Node node) {
273	            if (root == node) return false;
274	
275	            for (Node sib = node.firstSibling(); sib != null; sib = sib.nextSibling()) {
276	                if (sib == node) break;
277	                if (memoMatches(root, sib)) return true;
278	            }
279	
280	            return false;
281	        }
282	
283	        @Override protected int cost() {
284	            return 3 * evaluator.cost();
285	        }
286	
287	        @Override
288	        public String toString() {
289	            return String.format("%s ~ ", evaluator);
290	        }
291	    }
292	
293	    static class ImmediatePreviousSibling extends StructuralEvaluator {
294	        public ImmediatePreviousSibling(Evaluator evaluator) {
295	            super(evaluator);
296	        }
297	
298	        @Override boolean evaluateMatch(Element root, Node node) {
299	            if (root == node) return false;
300	
301	            Node prev = wantsNodes ? node.previousSibling() : node.previousElementSibling();
302	            return prev != null && memoMatches(root, prev);
303	        }
304	
305	        @Override protected int cost() {
306	            return 2 + evaluator.cost();
307	        }
308	
309	        @Override
310	        public String toString() {
311	            return String.format("%s + ", evaluator);
312	        }
313	    }
