30	    public static Elements collect(Evaluator eval, Element root) {
31	        Stream<Element> stream = eval.wantsNodes() ?
32	            streamNodes(eval, root, Element.class) :
33	            stream(eval, root);
34	        Elements els = stream.collect(toCollection(Elements::new));
35	        eval.reset(); // drops any held memos
36	        return els;
