import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;

public class NthOfCheck {
    public static void main(String[] args) {
        Document doc = Jsoup.parse(
            "<i id=a class=x></i><i id=b></i><i id=c class=x></i>"
            + "<i id=d class=x></i><i id=e></i><i id=f class=x></i>");

        // case-insensitive OF keyword
        System.out.println("upper OF: " + doc.select("i:nth-child(2n OF .x)").eachAttr("id"));
        // extra whitespace / tabs around of
        System.out.println("tabs: " + doc.select("i:nth-child(2n\tof\t.x)").eachAttr("id"));
        // no whitespace around of -> must not be a delimiter -> invalid formula
        try { doc.select("i:nth-child(2nof.x)"); System.out.println("no-space: NO ERROR (bad)"); }
        catch (Selector.SelectorParseException ex) { System.out.println("no-space: parse error (good): " + ex.getMessage()); }
        // 'odd of' shorthand
        System.out.println("odd of: " + doc.select("i:nth-child(odd of .x)").eachAttr("id"));
        // is() on rootless / orphan element
        org.jsoup.nodes.Element orphan = Jsoup.parseBodyFragment("<i class=x></i>").body().child(0).clone();
        System.out.println("orphan is: " + orphan.is("i:nth-child(1 of .x)"));
        // reused compiled evaluator across docs (thread-safety / reset)
        var ev = org.jsoup.select.Selector.evaluatorOf("i:nth-child(2n of .x)");
        System.out.println("reuse1: " + org.jsoup.select.Collector.collect(ev, doc).eachAttr("id"));
        Document doc2 = Jsoup.parse("<i id=p class=x></i><i id=q class=x></i><i id=r class=x></i>");
        System.out.println("reuse2: " + org.jsoup.select.Selector.select("i:nth-child(2n of .x)", java.util.List.of(doc, doc2)).eachAttr("id"));
    }
}
