import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;

public class OfErr {
    public static void main(String[] a) {
        Document doc = Jsoup.parse("<i class=x id=a></i><i class=x id=b></i>");
        check(doc, "i:nth-child(2n of)");          // empty list
        check(doc, "i:nth-child(2n of )");         // empty list w/ space
        check(doc, "i:nth-child(2n of .x of)");    // multiple of (2nd at end)
        check(doc, "i:nth-child(2n of .x of .y)"); // multiple of
        check(doc, "i:nth-child( 2n  of  .x )");   // tolerant inner whitespace
        System.out.println(doc.select("i:nth-child( 2n  of  .x )").eachAttr("id"));
    }
    static void check(Document d, String q) {
        try { d.select(q); System.out.println(q + " -> NO ERROR (bad)"); }
